 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Full separator of color 2; translate the lone motif toward it, then
    # mark the next line beyond the motif with 8.
    sr = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    sc = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    if sr is None and sc is None:
        return out
    other = {v for row in grid for v in row if v not in (2, 5, 7, 8)}
    if len(other) != 1:
        # Generic background/motif discrimination: choose least frequent non-divider color.
        counts = {}
        for row in grid:
            for v in row:
                if v != 2:
                    counts[v] = counts.get(v, 0) + 1
        motif = min(counts, key=counts.get)
    else:
        motif = next(iter(other))
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == motif]
    if not cells:
        return out
    if sr is not None:
        top, bottom = min(r for r, c in cells), max(r for r, c in cells)
        shift = sr + 1 - top if sr < top else sr - 1 - bottom
        # clear original motif to the background, then place translated motif
        bg = max((v for v in set(sum(grid, [])) if v not in (2, motif, 8)), key=lambda v:sum(row.count(v) for row in grid), default=7)
        for r, c in cells: out[r][c] = bg
        for r, c in cells: out[r + shift][c] = motif
        far = (top + shift - 1) if shift > 0 else (bottom + shift + 1)
        if 0 <= far < h:
            for c in range(w):
                if out[far][c] != 2: out[far][c] = 8
    else:
        left, right = min(c for r, c in cells), max(c for r, c in cells)
        shift = sc + 1 - left if sc < left else sc - 1 - right
        bg = max((v for v in set(sum(grid, [])) if v not in (2, motif, 8)), key=lambda v:sum(row.count(v) for row in grid), default=7)
        for r, c in cells: out[r][c] = bg
        for r, c in cells: out[r][c + shift] = motif
        far = (left + shift - 1) if shift > 0 else (right + shift + 1)
        if 0 <= far < w:
            for r in range(h):
                if out[r][far] != 2: out[r][far] = 8
    return out

